window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d85aac0c1e6055ea"]={"versions": [{"id": "FIG-d85aac0c1e6055ea", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Dateistruktur- und Inklusionsdiagramm (Include-Hierarchie) der AUTOSAR Classic Platform Bibliothek CRC Library (<code>Crc</code>). Es zeigt die Header- und Quelldatei-Abhängigkeiten auf Implementierungsebene sowie die Einbindung übergeordneter Plattform- und Speicherkonfigurationen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert fünf Datei-Entitäten und deren Inklusionsbeziehungen:</p>\n<ul class=\"fig-list\"><li><code>Crc_xxx.c</code>: Quellcodedatei(en) der CRC-Bibliothek, bindet <code>Crc.h</code> ein (<code>includes</code>).\n</li><li><code>Crc.h</code>: Zentraler Header der CRC-Bibliothek. Bindet <code>Crc_Cfg.h</code> und <code>Std_Types.h</code> ein (<code>includes</code>).\n</li><li><code>Crc_Cfg.h</code>: Modulspezifische Konfigurations-Headerdatei, bindet <code>Crc_MemMap.h</code> ein (<code>includes</code>).\n</li><li><code>Std_Types.h</code>: Standard-Typdefinitionen der AUTOSAR-Plattform, von <code>Crc.h</code> inkludiert.\n</li><li><code>Crc_MemMap.h</code>: Speicherkartierungs-Headerdatei zur Compiler- und Linker-Abstraktion, von <code>Crc_Cfg.h</code> inkludiert.\n</li></ul>\n<p class=\"fig-p\">Alle Beziehungen sind gerichtete Include-Abhängigkeiten (<code>includes</code>), dargestellt durch Pfeile vom Inkludierenden zum Inkludierten.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Include-Hierarchie zur Übersetzungszeit (Kompilierzeitabhängigkeit):</p>\n<ol class=\"fig-list\"><li><code>Crc_xxx.c</code> inkludiert <code>Crc.h</code>.\n</li><li><code>Crc.h</code> inkludiert transitiv <code>Std_Types.h</code> für Basistypen sowie <code>Crc_Cfg.h</code> für modulspezifische Schalter und Tabellenkonfigurationen.\n</li><li><code>Crc_Cfg.h</code> inkludiert <code>Crc_MemMap.h</code> zur Steuerung des Speicherlayouts von Daten und Codebereichen.\n</li></ol>\n<p class=\"fig-p\">Es liegt kein dynamischer Laufzeitablauf vor.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für die Modulstruktur und Include-Hierarchie der CRC-Bibliothek. Implementierungen müssen sicherstellen, dass Anwender oder interne Implementierungsdateien (<code>Crc_xxx.c</code>) über <code>Crc.h</code> vollständigen Zugriff auf Konfiguration (<code>Crc_Cfg.h</code>) und Standardtypen (<code>Std_Types.h</code>) erhalten. <code>Crc_MemMap.h</code> muss konform zum AUTOSAR-Speicherzuweisungskonzept eingebunden werden. Zyklische Abhängigkeiten sind ausgeschlossen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-181412c5ec51967d", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Dateistruktur- und Inklusionsdiagramm (Include-Hierarchie) der AUTOSAR Classic Platform Bibliothek CRC Library (<code>Crc</code>). Es zeigt die Header- und Quelldatei-Abhängigkeiten auf Implementierungsebene sowie die Einbindung übergeordneter Plattform- und Speicherkonfigurationen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert fünf Datei-Entitäten und deren Inklusionsbeziehungen:</p>\n<ul class=\"fig-list\"><li><code>Crc_xxx.c</code>: Quellcodedatei(en) der CRC-Bibliothek, bindet <code>Crc.h</code> ein (<code>includes</code>).\n</li><li><code>Crc.h</code>: Zentraler Header der CRC-Bibliothek. Bindet <code>Crc_Cfg.h</code> und <code>Std_Types.h</code> ein (<code>includes</code>).\n</li><li><code>Crc_Cfg.h</code>: Modulspezifische Konfigurations-Headerdatei, bindet <code>Crc_MemMap.h</code> ein (<code>includes</code>).\n</li><li><code>Std_Types.h</code>: Standard-Typdefinitionen der AUTOSAR-Plattform, von <code>Crc.h</code> inkludiert.\n</li><li><code>Crc_MemMap.h</code>: Speicherkartierungs-Headerdatei zur Compiler- und Linker-Abstraktion, von <code>Crc_Cfg.h</code> inkludiert.\n</li></ul>\n<p class=\"fig-p\">Alle Beziehungen sind gerichtete Include-Abhängigkeiten (<code>includes</code>), dargestellt durch Pfeile vom Inkludierenden zum Inkludierten.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Include-Hierarchie zur Übersetzungszeit (Kompilierzeitabhängigkeit):</p>\n<ol class=\"fig-list\"><li><code>Crc_xxx.c</code> inkludiert <code>Crc.h</code>.\n</li><li><code>Crc.h</code> inkludiert transitiv <code>Std_Types.h</code> für Basistypen sowie <code>Crc_Cfg.h</code> für modulspezifische Schalter und Tabellenkonfigurationen.\n</li><li><code>Crc_Cfg.h</code> inkludiert <code>Crc_MemMap.h</code> zur Steuerung des Speicherlayouts von Daten und Codebereichen.\n</li></ol>\n<p class=\"fig-p\">Es liegt kein dynamischer Laufzeitablauf vor.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für die Modulstruktur und Include-Hierarchie der CRC-Bibliothek. Implementierungen müssen sicherstellen, dass Anwender oder interne Implementierungsdateien (<code>Crc_xxx.c</code>) über <code>Crc.h</code> vollständigen Zugriff auf Konfiguration (<code>Crc_Cfg.h</code>) und Standardtypen (<code>Std_Types.h</code>) erhalten. <code>Crc_MemMap.h</code> muss konform zum AUTOSAR-Speicherzuweisungskonzept eingebunden werden. Zyklische Abhängigkeiten sind ausgeschlossen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-d85aac0c1e6055ea", "to": "FIG-181412c5ec51967d", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
